--
-- Table structure for table `agent_runs`
--

DROP TABLE IF EXISTS `agent_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agent_runs` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `thread_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'LangGraph 会话 ID',
  `question` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户问题',
  `user_id` int DEFAULT NULL COMMENT '提问用户',
  `route` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'structured / semantic',
  `evidence_source` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证据来源',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行状态',
  `elapsed_ms` int DEFAULT NULL COMMENT '总耗时毫秒',
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因（对用户可见的简短文案）',
  `answer_preview` text COLLATE utf8mb4_unicode_ci COMMENT '回答摘要（截断）',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `ix_agent_runs_thread_id` (`thread_id`),
  CONSTRAINT `agent_runs_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent 运行记录';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `agent_runs`
--

LOCK TABLES `agent_runs` WRITE;
/*!40000 ALTER TABLE `agent_runs` DISABLE KEYS */;
INSERT INTO `agent_runs` VALUES (1,'63add855-a756-454f-9077-19745e85707c','静音蓝牙耳机的差评有哪些？',1,'structured','structured','awaiting_confirm',34523,NULL,'根据查询结果，静音蓝牙耳机的差评主要集中在以下三点：\n- **单侧无声/疑似次品**：右耳没有声音，买家怀疑是质量问题（1星）\n- **降噪效果不足**：降噪表现一般，在地铁等嘈杂环境下基本听不清（2星）\n- **包装与外观瑕疵**：收货时包装破损，耳机充电仓有明显划痕（1星）\n\n以上为当前系统记录到的差评内容，供您运营参考。','2026-10-08 09:21:46','2026-10-08 09:22:20'),(2,'ca16fe02-70e4-42d9-926e-fdd9b3fdc7cc','查一下耳机',1,'structured','structured','success',18300,NULL,'为您查到“静音蓝牙耳机”的相关信息如下：\n\n* **商品名称**：静音蓝牙耳机\n* **商品分类**：数码\n* **商品描述**：入耳式蓝牙耳机，支持降噪，续航约 6 小时\n* **价格**：199.00 元\n* **当前库存**：80 件\n* **上下架状态**：在售\n* **审核状态**：正常\n* **创建时间**：2026-08-09 09:16:12\n* **最后更新时间**：2026-09-08 09:16:12','2026-10-08 09:23:39','2026-10-08 09:23:51'),(3,'2d5286a5-65d7-4db5-8a36-e736802e83a8','洗衣液有哪些评价？',1,'structured','structured','success',11452,NULL,'关于“洗衣液 2L”的评价共有2条，具体如下：\n\n1. **评分 4 星**：买家评价“洗净效果不错，味道清淡。”\n2. **评分 5 星**：买家评价“比超市便宜，会回购。”','2026-10-08 10:01:02','2026-10-08 10:01:13'),(4,'e54748f8-1183-46f1-89ca-7adb9c888bc9','跑鞋脱胶',1,'semantic','semantic','success',10873,NULL,'抱歉，目前没有查询到关于“跑鞋脱胶”的相关记录或反馈信息。','2026-10-08 10:03:20','2026-10-08 10:03:24'),(5,'4120791e-b98f-4e98-a31f-0b439b6fecc3','跑鞋脱胶',1,NULL,NULL,'error',125,'MCP 工具执行失败：query_chroma_tool',NULL,'2026-10-08 10:09:21','2026-10-08 10:09:21'),(6,'51a6a9ba-2c15-42f6-a715-629b050586d3','跑鞋脱胶',1,NULL,NULL,'error',102,'MCP 工具执行失败：query_chroma_tool',NULL,'2026-10-08 10:09:24','2026-10-08 10:09:25'),(7,'ef2e1ff7-035c-405a-a57e-f3955c47fe41','跑鞋脱胶',1,NULL,NULL,'error',98,'MCP 工具执行失败：query_chroma_tool',NULL,'2026-10-08 10:09:29','2026-10-08 10:09:29'),(8,'bf9eb6f9-4734-4a25-944c-4b4d9d96eb0d','跑鞋脱胶',1,'semantic','semantic','awaiting_confirm',14161,NULL,'根据查询结果，关于“跑鞋脱胶”的问题，具体情况如下：\n\n* **涉及商品**：轻云运动跑鞋\n* **脱胶问题反馈**：有买家反馈该跑鞋穿了两周后出现鞋底开胶，质量较差。买家晒图显示，鞋底外侧（足弓至前脚掌处）存在大面积开胶和断裂，中底与鞋面完全分离。\n* **其他相关反馈**：除脱胶外，该跑鞋还存在鞋帮磨脚、尺码偏大、鞋垫偏硬走久脚疼等差评问题。','2026-10-08 10:10:29','2026-10-08 10:10:44'),(9,'9669e978-9e92-4090-a43e-228bf3efb680','跑鞋脱胶',1,'semantic','semantic','awaiting_confirm',16940,NULL,'关于“跑鞋脱胶”的问题，根据查询结果，相关反馈如下：\n\n- **涉及商品**：轻云运动跑鞋\n- **脱胶/开胶情况**：有买家反馈该跑鞋穿了两周后鞋底开胶。买家晒图显示，鞋底外侧（足弓至前脚掌处）出现大面积开胶和断裂，中底与鞋面完全分离。\n- **其他相关反馈**：除脱胶外，该跑鞋还存在鞋帮磨脚、尺码偏大、鞋垫偏硬走久脚疼等负面评价。','2026-10-08 10:10:56','2026-10-08 10:11:13'),(10,'c92bacd0-791b-48d0-a414-2ab4db42d23c','跑鞋脱胶',1,NULL,NULL,'error',4841,'MCP 工具执行失败：query_chroma_tool',NULL,'2026-10-08 10:13:53','2026-10-08 10:13:53'),(11,'0dc4758c-3306-4c0a-b758-03854e053e1b','跑鞋脱胶',1,NULL,NULL,'error',5388,'MCP 工具执行失败：query_chroma_tool',NULL,'2026-10-08 10:14:40','2026-10-08 10:14:40'),(12,'6f0b6239-f20e-4e54-9327-2c1cd8e4ee2b','跑鞋脱胶',1,'semantic','semantic','success',22492,NULL,'根据查询结果，关于“跑鞋脱胶”的情况如下：\n\n**轻云运动跑鞋** 存在脱胶/开胶的质量问题反馈：\n* **开胶严重**：有买家反馈穿了两周后鞋底开胶，鞋底外侧（足弓至前脚掌处）出现大面积开胶和断裂，中底与鞋面完全分离。\n* **图片证实**：买家晒图显示，鞋子中底与鞋面完全分离，露出内部黑色材质，存在严重缺陷。\n\n此外，该商品还存在鞋帮磨脚、尺码偏大、鞋垫偏硬等其他负面评价。','2026-10-08 10:20:21','2026-10-08 10:20:44'),(13,'4c0e5b35-a29c-439c-b9ab-4ad17e65ba28','洗衣液有哪些差评？',1,'structured','semantic','success',24752,NULL,'抱歉，没有查到关于洗衣液的差评数据。','2026-10-08 11:24:22','2026-10-08 11:24:47'),(14,'2d3afd30-8e41-4d27-8129-84fb5f24698d','洗衣液有哪些评价？',1,'structured','structured','success',15008,NULL,'关于“洗衣液 2L”的评价主要有以下两条：\n\n1. **4星评价**：“洗净效果不错，味道清淡。”\n2. **5星评价**：“比超市便宜，会回购。”','2026-10-08 11:25:03','2026-10-08 11:25:18'),(15,'6205be0e-7927-4993-9ec6-e5472e8db1c4','羽绒服这个商品最近怎么样',1,'structured','semantic','success',33912,NULL,'抱歉，没有查到关于“羽绒服洗衣液 2L”的相关数据或记录。','2026-10-08 11:27:17','2026-10-08 11:27:51'),(16,'6e6dd945-4f72-4c7d-bea7-c96eaa0a3374','羽绒服这个商品最近怎么样',1,'semantic','semantic','success',13991,NULL,'根据查询结果，关于“羽绒服轻薄款”近期的情况如下：\n\n**1. 商品基本信息**\n* 采用 90% 白鸭绒，可收纳成小袋。\n* 尺码偏小，建议顾客拍大一码。\n\n**2. 近期顾客评价反馈**\n* **版型问题**：有顾客反馈保暖性尚可，但袖子偏短（3星评价）。\n* **做工问题**：有顾客反馈充绒不均匀，出现一边厚一边薄的情况，给出了1星差评。\n\n**总结**：近期顾客对该款羽绒服的评价整体偏低，主要槽点集中在“袖子偏短”和“充绒不均匀”上，同时需留意商品本身尺码偏小的情况。','2026-10-08 11:28:56','2026-10-08 11:29:10'),(17,'7d4a179e-9a48-4e8f-af7e-98c810e56912','羽绒服有哪些差评',1,'structured','structured','success',32249,NULL,'根据查询结果，关于“羽绒服轻薄款”的差评主要为：\n- 充绒不均匀，一边厚一边薄。','2026-10-08 11:29:38','2026-10-08 11:30:10'),(18,'916ed1aa-63ce-4eb0-8cbc-cfd8395ac022','静音蓝牙耳机的差评有哪些？',1,'structured','mixed','success',33078,NULL,'根据查询结果，静音蓝牙耳机的差评主要集中在以下三个方面：\n\n1. **质量故障**：有买家反馈右耳没有声音，怀疑是次品（相关图片显示右侧耳机外壳接缝处存在开裂缺陷）。\n2. **降噪效果不佳**：降噪表现一般，在地铁等嘈杂环境中基本听不清。\n3. **包装与外观瑕疵**：收到时外包装破损，且耳机充电仓表面有明显的划痕。','2026-10-08 11:30:27','2026-10-08 11:31:46'),(19,'d88565dd-296d-44bc-9239-88eda2c8df17','跑鞋脱胶',1,'semantic','semantic','success',15021,NULL,'关于“跑鞋脱胶”的问题，查询到以下反馈：\n\n* **轻云运动跑鞋**：有买家反馈穿了两周后出现鞋底开胶问题。具体表现为鞋底外侧（足弓至前脚掌处）大面积开胶和断裂，中底与鞋面完全分离，买家因此给出1星差评，认为质量太差。','2026-10-08 11:34:08','2026-10-08 11:34:42'),(20,'7b54d111-018c-4153-bd14-a8cee6f83fe2','跑鞋脱胶',2,'semantic','semantic','success',14408,NULL,'关于“跑鞋脱胶”的问题，查询结果如下：\n\n* **涉及商品**：轻云运动跑鞋\n* **脱胶问题反馈**：有买家反馈该跑鞋存在严重的脱胶问题。具体表现为穿了两周后鞋底开胶，鞋底外侧（足弓至前脚掌处）出现大面积开胶和断裂，中底与鞋面完全分离。\n* **其他相关反馈**：该商品还存在其他负面评价，包括鞋帮磨脚、尺码明显偏大、鞋垫偏硬导致走久脚疼等。','2026-10-08 11:37:54','2026-10-08 11:38:10'),(21,'735b06d9-5dcb-487e-ba39-ac4128ef6103','静音蓝牙耳机的差评有哪些？',1,'structured','mixed','success',30019,NULL,'根据查询结果，静音蓝牙耳机的差评主要集中在以下三个方面：\n\n1. **产品质量问题**：有买家反馈右耳没有声音，怀疑是次品；相关图片也显示右侧耳机外壳接缝处存在明显的开裂缺陷。\n2. **降噪效果不佳**：降噪效果一般，在地铁等嘈杂环境中基本听不清。\n3. **包装与外观瑕疵**：有买家反馈收到时包装破损，且耳机充电仓表面有明显的划痕。','2026-10-08 11:51:17','2026-10-08 11:52:18');
