INSERT INTO `products` VALUES (1,'轻云运动跑鞋','鞋靴','轻量网面跑鞋，适合日常慢跑与通勤，鞋码偏大半码。',299.00,120,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(2,'柔棉短袖T恤','服饰','100% 棉质短袖，多色可选，水洗后可能轻微缩水。',79.00,500,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(3,'静音蓝牙耳机','数码','入耳式蓝牙耳机，支持降噪，续航约 6 小时。',199.00,80,'on_sale','pending_review','2026-08-09 09:16:12','2026-10-08 11:31:46'),(4,'保温杯 500ml','家居','不锈钢保温杯，保温 6 小时，杯盖可拆洗。',89.00,200,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(5,'护脊书包','箱包','中学生护脊书包，分区收纳，肩带加宽。',159.00,60,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(6,'厨房刀具套装','家居','三件套不锈钢刀具，含刀架，开刃出厂。',129.00,90,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(7,'儿童益智积木','玩具','200 片积木，适合 3 岁以上，零件较小请家长看护。',99.00,150,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(8,'洗衣液 2L','日用','浓缩洗衣液，低泡易漂，适合机洗。',39.90,300,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(9,'防晒霜 SPF50','美妆','清爽防晒乳，适合油皮，防水防汗。',68.00,180,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(10,'机械键盘青轴','数码','87 键机械键盘，青轴手感，支持键帽热插拔。',249.00,70,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(11,'瑜伽垫 10mm','运动','加厚防滑瑜伽垫，附收纳绑带。',59.00,110,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(12,'不锈钢炒锅 32cm','家居','无涂层炒锅，适合电磁炉与燃气灶。',189.00,45,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(13,'速干运动短裤','服饰','透气速干面料，侧边口袋带拉链。',69.00,220,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(14,'插座排插 6位','家电','六位插孔带独立开关，线长 1.8 米。',49.00,160,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(15,'枕头慢回弹','家居','记忆棉枕头，透气外套可拆洗。',119.00,95,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(16,'无线鼠标静音','数码','2.4G 无线鼠标，静音按键，续航约 12 个月。',59.00,140,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(17,'帆布单肩包','箱包','日系帆布包，内含笔记本隔层。',89.00,75,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(18,'电动牙刷套装','个护','声波电动牙刷，含 2 支刷头，续航约 30 天。',159.00,85,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(19,'桌面小台灯','家居','三档亮度护眼台灯，USB 供电。',79.00,130,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12'),(20,'羽绒服轻薄款','服饰','90% 白鸭绒，可收纳成小袋，尺码偏小建议拍大一码。',399.00,55,'on_sale','normal','2026-08-09 09:16:12','2026-09-08 09:16:12');
