INSERT INTO `reviews` VALUES (1,1,1,5,'鞋子很轻，跑步不累脚，推荐。',NULL,'2026-10-05 09:16:12','2026-10-05 09:16:12'),(2,1,2,2,'尺码明显偏大，按平时码拍了结果松垮，客服让我自己垫鞋垫。',NULL,'2026-10-03 09:16:12','2026-10-03 09:16:12'),(3,1,3,1,'鞋底开胶了，穿了两周就这样，质量太差。','/uploads/review_samples/shoe_glue-demo.jpg','2026-09-30 09:16:12','2026-09-30 09:16:12'),(4,1,4,3,'外观还可以，但是鞋垫偏硬，走久了脚疼。',NULL,'2026-09-26 09:16:12','2026-09-26 09:16:12'),(5,2,5,5,'面料舒服，洗了不变形。',NULL,'2026-10-06 09:16:12','2026-10-06 09:16:12'),(6,2,6,2,'缩水严重，洗一次短了一截，差评。',NULL,'2026-10-02 09:16:12','2026-10-02 09:16:12'),(7,2,7,4,'颜色和图片差不多，性价比不错。',NULL,'2026-09-28 09:16:12','2026-09-28 09:16:12'),(8,3,8,1,'右耳没有声音，怀疑是次品。','/uploads/review_samples/earphone_broken-demo.jpg','2026-10-04 09:16:12','2026-10-04 09:16:12'),(9,3,9,2,'降噪一般，地铁里基本听不清。',NULL,'2026-10-01 09:16:12','2026-10-01 09:16:12'),(10,3,10,5,'音质超出预期，续航也够用。',NULL,'2026-09-23 09:16:12','2026-09-23 09:16:12'),(11,4,11,4,'保温效果可以，出门带水方便。',NULL,'2026-10-07 09:16:12','2026-10-07 09:16:12'),(12,4,12,1,'收到时杯盖裂了，包装也有压痕。','/uploads/review_samples/broken_box-demo.jpg','2026-09-29 09:16:12','2026-09-29 09:16:12'),(13,5,13,5,'背着挺舒服，孩子说分区好用。',NULL,'2026-09-27 09:16:12','2026-09-27 09:16:12'),(14,5,14,2,'拉链很容易卡住，质量一般。',NULL,'2026-09-24 09:16:12','2026-09-24 09:16:12'),(15,6,15,3,'刀还行，就是刀架塑料感太重。',NULL,'2026-10-05 09:16:12','2026-10-05 09:16:12'),(16,6,16,1,'刀刃有缺口，感觉是返修货。',NULL,'2026-09-22 09:16:12','2026-09-22 09:16:12'),(17,7,17,5,'孩子很喜欢，拼了好久。',NULL,'2026-10-06 09:16:12','2026-10-06 09:16:12'),(18,7,18,2,'少了好几块零件，联系客服补发很慢。',NULL,'2026-09-30 09:16:12','2026-09-30 09:16:12'),(19,8,19,4,'洗净效果不错，味道清淡。',NULL,'2026-10-03 09:16:12','2026-10-03 09:16:12'),(20,8,20,5,'比超市便宜，会回购。',NULL,'2026-09-25 09:16:12','2026-09-25 09:16:12'),(21,9,21,2,'涂完闷痘，油皮慎入。',NULL,'2026-10-04 09:16:12','2026-10-04 09:16:12'),(22,9,22,5,'不油腻，户外一天没有晒黑。',NULL,'2026-09-20 09:16:12','2026-09-20 09:16:12'),(23,10,23,1,'有好几个键失灵，退货中。',NULL,'2026-10-02 09:16:12','2026-10-02 09:16:12'),(24,10,24,4,'青轴清脆，打字爽。',NULL,'2026-09-18 09:16:12','2026-09-18 09:16:12'),(25,11,25,5,'厚度够，跪姿也不疼。',NULL,'2026-10-01 09:16:12','2026-10-01 09:16:12'),(26,11,26,3,'味道有点大，晾了两天才好。',NULL,'2026-09-29 09:16:12','2026-09-29 09:16:12'),(27,12,27,2,'手柄焊接处有毛刺，割手。',NULL,'2026-09-27 09:16:12','2026-09-27 09:16:12'),(28,12,28,5,'炒菜受热均匀，好用。',NULL,'2026-09-21 09:16:12','2026-09-21 09:16:12'),(29,13,29,4,'透气好，跑步出汗也能干得快。',NULL,'2026-10-05 09:16:12','2026-10-05 09:16:12'),(30,13,30,1,'尺码标错了，XL 穿起来像 M。',NULL,'2026-09-26 09:16:12','2026-09-26 09:16:12'),(31,14,31,5,'插孔够用，线也不短。',NULL,'2026-10-07 09:16:12','2026-10-07 09:16:12'),(32,14,32,2,'有一个开关按下去弹不起来。',NULL,'2026-09-24 09:16:12','2026-09-24 09:16:12'),(33,15,33,4,'睡着很舒服，回弹慢。',NULL,'2026-10-03 09:16:12','2026-10-03 09:16:12'),(34,15,34,1,'拆开有股刺鼻味道，怀疑不合格。',NULL,'2026-09-19 09:16:12','2026-09-19 09:16:12'),(35,16,35,5,'静音效果真好，办公室用很合适。',NULL,'2026-10-06 09:16:12','2026-10-06 09:16:12'),(36,16,36,3,'偶发卡顿，换电池后好了。',NULL,'2026-09-28 09:16:12','2026-09-28 09:16:12'),(37,17,37,4,'容量大，通勤够用。',NULL,'2026-09-30 09:16:12','2026-09-30 09:16:12'),(38,17,38,2,'肩带缝线开了，用了不到一个月。',NULL,'2026-09-17 09:16:12','2026-09-17 09:16:12'),(39,18,39,5,'刷牙干净，震动力度合适。',NULL,'2026-10-04 09:16:12','2026-10-04 09:16:12'),(40,18,40,1,'充电座接触不良，经常充不进电。',NULL,'2026-09-23 09:16:12','2026-09-23 09:16:12'),(41,19,41,4,'亮度够，夜间看书写作业可以。',NULL,'2026-10-02 09:16:12','2026-10-02 09:16:12'),(42,19,42,2,'按钮松动，一碰就自己切换档位。',NULL,'2026-09-25 09:16:12','2026-09-25 09:16:12'),(43,20,43,3,'保暖可以，但袖子偏短。',NULL,'2026-10-01 09:16:12','2026-10-01 09:16:12'),(44,20,44,1,'充绒不均匀，一边厚一边薄。',NULL,'2026-09-16 09:16:12','2026-09-16 09:16:12'),(45,1,45,2,'最近这双鞋差评好像变多了，我也中招，鞋帮磨脚。',NULL,'2026-10-07 09:16:12','2026-10-07 09:16:12'),(46,3,46,1,'包装破损，耳机仓有明显划痕。','/uploads/review_samples/package_scratch-demo.jpg','2026-10-06 09:16:12','2026-10-06 09:16:12');
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
